import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, sin } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let cleaned = false;

  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const makeBasic = (color, options = {}) => {
    const material = new MeshBasicNodeMaterial({
      color,
      side: DoubleSide,
      ...options
    });
    resources.push(material);
    return material;
  };

  const backdropMaterial = new MeshBasicNodeMaterial({
    side: DoubleSide
  });
  const backdropUv = uv();
  const backdropGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    backdropUv.y
  );
  const grain = sin(
    backdropUv.x.mul(191.0).add(backdropUv.y.mul(137.0))
  ).mul(0.009);
  backdropMaterial.colorNode = backdropGradient.add(vec3(grain));
  resources.push(backdropMaterial);

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const surfaceMaterial = makeBasic(palette.surface, {
    transparent: true,
    opacity: 0.94
  });
  const surfacePanel = new Mesh(
    new PlaneGeometry(5.85, 3.25),
    surfaceMaterial
  );
  surfacePanel.position.set(0.15, -0.05, -1.15);
  root.add(surfacePanel);

  const imageMaterial = makeBasic(palette.paper, {
    transparent: true,
    opacity: 0.98
  });
  const imagePlane = new Mesh(
    new PlaneGeometry(4.9, 2.76),
    imageMaterial
  );
  imagePlane.position.set(0.38, -0.02, -0.72);
  root.add(imagePlane);

  const accentMaterial = makeBasic(palette.accent, {
    transparent: true,
    opacity: 0.95
  });
  const accentRule = new Mesh(
    new PlaneGeometry(0.055, 2.35),
    accentMaterial
  );
  accentRule.position.set(-2.42, 0.13, -0.45);
  root.add(accentRule);

  const paperMaterial = makeBasic(palette.paper, {
    transparent: true,
    opacity: 0.9
  });
  const paperRule = new Mesh(
    new PlaneGeometry(1.05, 0.018),
    paperMaterial
  );
  paperRule.position.set(-2.12, 1.22, -0.43);
  root.add(paperRule);

  const textGroup = new Group();
  textGroup.position.set(-2.05, 0.67, 0.08);
  root.add(textGroup);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  let textOffset = 0;
  for (const item of items) {
    const content = String(item?.text ?? '');
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item?.typography?.fontSize ?? 31,
      color: palette.paper,
      align: 'left',
      maxWidthPx: 560,
      letterSpacingPx: 0
    });

    textObject.position.set(0, -textOffset, 0);
    textGroup.add(textObject);
    textOffset += 0.62;
  }

  const caption = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 16,
    color: palette.accent,
    align: 'left',
    maxWidthPx: 300,
    letterSpacingPx: 2
  });
  caption.position.set(-2.05, 1.52, 0.1);
  root.add(caption);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (cleaned) {
        texture.dispose?.();
        return;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive === 'function') {
      const result = applyPrimitive(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') {
        timelines.push({ kill: result.cleanup });
      }
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const timeline of timelines) {
      try {
        timeline?.kill?.();
      } catch {}
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material && object.material !== backdropMaterial) {
        if (Array.isArray(object.material)) {
          for (const material of object.material) material.dispose?.();
        } else {
          object.material.dispose?.();
        }
      }
    });

    for (const resource of resources) {
      try {
        resource?.dispose?.();
      } catch {}
    }
  };

  return root;
}
